mapper.update:
UPDATE g5_member
SET recommended_mb_id = #{recommendedMbId}
WHERE mb_no = #{mbNo}

UPDATE g5_member
SET mb_point = (mb_point + #{point})
WHERE mb_id = #{mbId};

mapper.select:
SELECT IFNULL(mb_point, 0)
FROM g5_member
WHERE mb_id = #{mbId}

SELECT count(*)
FROM g5_member
WHERE mb_recommend = #{mbRecommend}

SELECT COUNT(*)
FROM g5_member
WHERE mb_id = #{mbId}
AND (
mb_nick_date = '0000-00-00'
OR mb_nick_date  <=DATE_SUB(NOW(), INTERVAL 30 DAY)
);

SELECT count(*)
FROM g5_shop_order
WHERE mb_id = #{mbId}
AND od_status NOT IN ('완료','취소완료','반품정산완료');

