UPDATE g5_member
SET mb_mailling   = #{mbMailingSms},
mb_sms        = #{mbMailingSms},
mb_alarm_date = #{mbAlarmDate}
WHERE mb_id = #{mbId}
AND mb_leave_date = ''

UPDATE pet_device_info
SET device_token = #{deviceToken}
WHERE mb_id = #{mbId} AND device_token != #{deviceToken};
